def _truncate(text: str, limit: int) -> tuple[str, bool]:
    limit = max(0, limit)
    if len(text) <= limit:
        return (text, False)
    if limit <= 5:
        return (text[:limit], True)
    prefix_length = limit * 2 // 5
    suffix_length = limit - prefix_length - 3
    return (text[:prefix_length] + ' … ' + text[-suffix_length:], True)

