def _apply_budgets(items: list[dict], max_items: int=MAX_ITEMS, max_chars: int=MAX_CHARS) -> tuple[list[dict], bool]:
    kept: list[dict] = []
    total = 0
    dropped = False
    for item in items:
        if len(item['text']) > MAX_CHARS:
            dropped = True
            continue
        if len(kept) >= max(0, max_items) or total + len(item['text']) > max(0, max_chars):
            return (kept, True)
        kept.append(item)
        total += len(item['text'])
    return (kept, dropped)

