import re
from types import SimpleNamespace
def Path(s): return SimpleNamespace(name=s.rsplit('/', 1)[-1])
_PYLOCK_FILE_NAME_RE = re.compile(r'^pylock\.([a-z0-9_-]{1,16})\.toml$')

def is_valid_pylock_path(path: Path) -> bool:
    return path.name == 'pylock.toml' or bool(_PYLOCK_FILE_NAME_RE.match(path.name))
```

